    Map<String,Object> limits(){return Map.of("requestTimeoutMs",1000,"maxAttempts",2,"retryMinMs",1000,"retryMaxMs",2000,"jitterRatio",0.0,"deliveryTtlMs",10000,"maxPayloadBytes",16384,"maxResponseBytes",128);}
    String channel(F f,String origin)throws Exception{outbound.setAllowedWebhookOrigins(List.of(origin));outbound.setAllowHttpOrigins(List.of(origin));outbound.setAllowedWebhookCidrs(List.of("127.0.0.1/32"));return body(member(f,post("/api/v1/workspaces/"+f.ws()+"/notification-channels"),Map.of("expectedVersion","0","name","合成通知端","url",origin+"/private?key=synthetic-channel-secret","hmacSecret","synthetic-hmac-secret","enabled",true,"limits",limits())).andExpect(status().isCreated())).path("id").asText();}
