    JsonNode notification(F f)throws Exception{var page=body(member(f,get("/api/v1/workspaces/"+f.ws()+"/notifications"),Map.of()).andExpect(status().isOk()));for(var item:page.path("items"))if(item.path("projectId").asText().equals(f.project()))return item;throw new AssertionError("Current project notification missing");}
