    @Test void observedSourceAtomicallyCreatesOneVersionedFixedBodyDelivery()throws Exception{
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String channel=channel(f,endpoint.origin("127.0.0.1"));source(f,channel);var event=notification(f);
            assertThat(event.path("notificationState").asText()).isEqualTo("pending");assertThat(event.path("deliveries").size()).isEqualTo(1);assertThat(event.at("/deliveries/0/channelVersion").asText()).isEqualTo("1");assertThat(endpoint.count).hasValue(0);
            var row=jdbc.queryForMap("SELECT event_id,body_json,body_hash,channel_version,attempts FROM execution_notification_outbox WHERE event_id=?",Long.valueOf(event.path("id").asText()));assertThat(row.get("event_id").toString()).isEqualTo(event.path("id").asText());assertThat(row.get("body_hash")).isEqualTo(com.autumnharvestc.server.core.Hashes.sha256Hex(row.get("body_json").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThat(row.get("attempts")).isEqualTo(0);
            notification(f);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_notification_outbox WHERE event_id=?",Long.class,Long.valueOf(event.path("id").asText()))).isEqualTo(1);
        }
    }
    @Test void deploymentReductionClampsNewDeliveriesWithoutRewritingTheExistingFixedBudget()throws Exception{
        int attempts=outbound.getMaxAttempts(),response=outbound.getMaxResponseBytes();long ttl=outbound.getDeliveryTtlMs();try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));source(f,ch);String first=notification(f).path("id").asText();outbound.setMaxAttempts(1);outbound.setDeliveryTtlMs(5000);outbound.setMaxResponseBytes(64);source(f,ch);String second=notification(f).path("id").asText();var fixed=json.readTree(jdbc.queryForObject("SELECT limits_json FROM execution_notification_outbox WHERE event_id=?",String.class,Long.valueOf(second)));assertThat(fixed.path("maxAttempts").asInt()).isEqualTo(1);assertThat(fixed.path("deliveryTtlMs").asLong()).isEqualTo(5000);assertThat(fixed.path("maxResponseBytes").asInt()).isEqualTo(64);var old=json.readTree(jdbc.queryForObject("SELECT limits_json FROM execution_notification_outbox WHERE event_id=?",String.class,Long.valueOf(first)));assertThat(old.path("maxAttempts").asInt()).isEqualTo(2);assertThat(old.path("deliveryTtlMs").asLong()).isEqualTo(10000);assertThat(endpoint.count).hasValue(0);
        }finally{outbound.setMaxAttempts(attempts);outbound.setDeliveryTtlMs(ttl);outbound.setMaxResponseBytes(response);}
    }
