    @Test void anOldPendingDeliveryStillUsesTheCurrentDeploymentSingleSendDeadline()throws Exception{
        long timeout=outbound.getRequestTimeoutMs();try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{try{Thread.sleep(2200);e.sendResponseHeaders(204,-1);}catch(Exception ignored){}finally{e.close();}})){var f=fixture();now(origin);String ch=channel(f,endpoint.origin("127.0.0.1"));var config=new LinkedHashMap<>(limits());config.put("requestTimeoutMs",3000);member(f,put("/api/v1/workspaces/"+f.ws()+"/notification-channels/"+ch),Map.of("expectedVersion","1","limits",config)).andExpect(status().isOk());source(f,ch);String event=notification(f).path("id").asText();outbound.setRequestTimeoutMs(1000);long start=System.nanoTime();outbox.deliverOne();assertThat(java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)).isLessThan(1800);assertThat(notification(f).at("/deliveries/0/reasonCode").asText()).isEqualTo("timeout");assertThat(json.readTree(jdbc.queryForObject("SELECT limits_json FROM execution_notification_outbox WHERE event_id=?",String.class,Long.valueOf(event))).path("requestTimeoutMs").asInt()).isEqualTo(3000);
        }finally{outbound.setRequestTimeoutMs(timeout);}
    }
    @Test void anAmbientDatabaseTransactionCannotBecomeASendingScope(){assertThatThrownBy(()->gatedTransactions.execute(s->{outbox.deliverOne();return null;})).isInstanceOf(IllegalStateException.class);}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"lost-ack","408","429","500","302"})
    void retryIsBoundedAndUsesTheSameEventAndBodyWithoutBusinessResubmission(String mode)throws Exception{
        var received=new java.util.concurrent.CopyOnWriteArrayList<byte[]>();var ids=new java.util.concurrent.CopyOnWriteArrayList<String>();
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{received.add(e.getRequestBody().readAllBytes());ids.add(e.getRequestHeaders().getFirst("X-Apicc-Event-Id"));if(received.size()==1&&mode.equals("lost-ack")){e.close();return;}e.getResponseHeaders().set("Location","/must-not-follow");e.sendResponseHeaders(received.size()==1?Integer.parseInt(mode):204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));source(f,ch);String event=notification(f).path("id").asText();outbox.deliverOne();assertThat(endpoint.count).hasValue(1);var first=notification(f);assertThat(first.at("/deliveries/0/attempts").asInt()).isEqualTo(1);
            if(mode.equals("302")){assertThat(first.path("notificationState").asText()).isEqualTo("failed");now(origin.plusSeconds(363));outbox.deliverOne();assertThat(endpoint.count).hasValue(1);}else{assertThat(first.path("notificationState").asText()).isEqualTo("pending");outbox.deliverOne();assertThat(endpoint.count).hasValue(1);now(origin.plusSeconds(363));outbox.deliverOne();assertThat(endpoint.count).hasValue(2);assertThat(notification(f).path("notificationState").asText()).isEqualTo("acknowledged");assertThat(received.get(1)).isEqualTo(received.get(0));assertThat(ids).containsExactly(event,event);}
            assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_jobs WHERE project_id=?",Long.class,Long.valueOf(f.project()))).isZero();
        }
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"address","key","disabled","deleted"})
    void channelChangesImmediatelyStopTheOldUnconfirmedVersion(String change)throws Exception{
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));source(f,ch);notification(f);String path="/api/v1/workspaces/"+f.ws()+"/notification-channels/"+ch;
            if(change.equals("deleted"))member(f,delete(path+"?expectedVersion=1"),Map.of()).andExpect(status().isNoContent());else{var update=new LinkedHashMap<String,Object>();update.put("expectedVersion","1");update.put(change.equals("address")?"url":change.equals("key")?"hmacSecret":"enabled",change.equals("address")?endpoint.origin("127.0.0.1")+"/new-address":change.equals("key")?"new-synthetic-signature-secret":false);member(f,put(path),update).andExpect(status().isOk());}
            var event=notification(f);assertThat(event.at("/deliveries/0/state").asText()).isEqualTo("stopped");assertThat(event.at("/deliveries/0/reasonCode").asText()).isEqualTo("channel-changed");outbox.deliverOne();assertThat(endpoint.count).hasValue(0);
        }
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"global","workspace","project"})
    void capacityRejectionIsTerminalAndCannotBeRecreatedWhenCapacityFrees(String scope)throws Exception{
        long old=outbound.getMaxPendingDeliveries();String policy=null;String next=null;
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));
            if(scope.equals("global"))outbound.setMaxPendingDeliveries(1);else{policy=scope.equals("workspace")?"/api/v1/workspaces/"+f.ws()+"/schedule-policy":f.url()+"/schedule-policy";String version=body(member(f,get(policy),Map.of()).andExpect(status().isOk())).path("version").asText();next=body(member(f,put(policy),Map.of("expectedVersion",version,"policy",Map.of("maxPendingDeliveries",1))).andExpect(status().isOk())).path("version").asText();}
            try{source(f,ch);notification(f);source(f,ch);var second=notification(f);assertThat(second.path("notificationState").asText()).isEqualTo("failed");assertThat(second.at("/deliveries/0/reasonCode").asText()).isEqualTo("notification-capacity");String id=second.path("id").asText();outbox.deliverOne();assertThat(endpoint.count).hasValue(1);notification(f);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_notification_outbox WHERE event_id=?",Long.class,Long.valueOf(id))).isEqualTo(1);assertThat(notification(f).path("id").asText()).isEqualTo(id);}
            finally{outbound.setMaxPendingDeliveries(old);if(policy!=null)member(f,put(policy),Map.of("expectedVersion",next,"policy",Map.of("maxPendingDeliveries",scope.equals("workspace")?1000:100))).andExpect(status().isOk());}
        }finally{outbound.setMaxPendingDeliveries(old);}
    }
