    @Test void detailCleanupKeepsDeduplicationHeadsAndHistoryAfterOccurrenceDeletion()throws Exception{
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));String plan=source(f,ch);String event=notification(f).path("id").asText();outbox.deliverOne();now(origin.plusSeconds(31L*86400));notificationRetention.clean();
            assertThat(jdbc.queryForObject("SELECT body_json FROM execution_notification_events WHERE id=?",String.class,Long.valueOf(event))).isNull();assertThat(jdbc.queryForObject("SELECT body_json FROM execution_notification_outbox WHERE event_id=?",String.class,Long.valueOf(event))).isNull();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_schedule_occurrences WHERE schedule_id=?",Long.class,Long.valueOf(plan))).isZero();
            events.observe(Long.valueOf(f.ws()));occurrences.scan("after-cleanup");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_notification_events WHERE source_id=(SELECT source_id FROM execution_notification_events WHERE id=?)",Long.class,Long.valueOf(event))).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM execution_notification_outbox WHERE event_id=?",Long.class,Long.valueOf(event))).isEqualTo(1);assertThat(endpoint.count).hasValue(1);
            var history=body(member(f,get(f.url()+"/schedules/"+plan+"/notification-history"),Map.of()).andExpect(status().isOk()));assertThat(history.at("/items/0/detailState").asText()).isEqualTo("expired");assertThat(history.at("/items/0/notificationState").asText()).isEqualTo("acknowledged");wire("t5-notification-history-expired",history);
        }
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"owner","token","lease","expired"})
    void aStaleSenderCannotOverwriteAChangedLeaseOrItsExpiry(String changed)throws Exception{
        var entered=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newSingleThreadExecutor();
        try(var endpoint=new WebhookTransportTest.Endpoint("127.0.0.1",e->{entered.countDown();try{release.await(3,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException ignored){}e.sendResponseHeaders(204,-1);e.close();})){var f=fixture();String ch=channel(f,endpoint.origin("127.0.0.1"));source(f,ch);String event=notification(f).path("id").asText();var sending=pool.submit(()->outbox.deliverOne());assertThat(entered.await(2,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
            if(changed.equals("owner"))jdbc.update("UPDATE execution_notification_outbox SET owner_id='new-owner' WHERE event_id=?",Long.valueOf(event));else if(changed.equals("token"))jdbc.update("UPDATE execution_notification_outbox SET lease_token='new-token' WHERE event_id=?",Long.valueOf(event));else if(changed.equals("lease"))jdbc.update("UPDATE execution_notification_outbox SET lease_until_utc=? WHERE event_id=?",origin.plusSeconds(400).atOffset(java.time.ZoneOffset.UTC),Long.valueOf(event));else now(origin.plusSeconds(400));release.countDown();sending.get(3,java.util.concurrent.TimeUnit.SECONDS);assertThat(jdbc.queryForObject("SELECT state FROM execution_notification_outbox WHERE event_id=?",String.class,Long.valueOf(event))).isEqualTo("sending");
        }finally{release.countDown();pool.shutdownNow();}
    }
